using System.Drawing;using System.Windows.Forms;using AshkanPharmacy.Core;
namespace AshkanPharmacy.Forms { public class ReceiptPreviewForm:Form { string receipt;public ReceiptPreviewForm(string text){receipt=text;Text="Invoice Preview";StartPosition=FormStartPosition.CenterParent;ClientSize=new Size(620,680);BackColor=Color.FromArgb(226,240,242);var box=new TextBox{Multiline=true,ReadOnly=true,ScrollBars=ScrollBars.Vertical,Text=text,Font=new Font("Consolas",10),Left=25,Top=25,Width=570,Height=550,BackColor=Color.FromArgb(249,252,251)};var print=new AccentButton{Text="Print invoice",Left=390,Top=600,Width=205,Height=48,BackColor=Theme.Teal,ForeColor=Color.White};print.Click+=(s,e)=>new InvoiceService(receipt).Print();Controls.Add(box);Controls.Add(print);} } }